if __name__ == "__main__":
    import inspect

    tests = [(name, obj) for name, obj in globals().items() if name.startswith("test_") and inspect.isfunction(obj)]
    passed = failed = 0
    for name, fn in tests:
        try:
            fn()
            passed += 1
            print(f"  ✓ {name}")
        except Exception as exc:
            failed += 1
            print(f"  ✗ {name}: {exc}")
    print(f"\n{passed} passed, {failed} failed")
    if failed:
        sys.exit(1)
